 LEFT JOIN information_schema.COLUMNS c ON c.TABLE_SCHEMA=DATABASE() AND c.TABLE_NAME=e.table_name AND c.COLUMN_NAME=e.column_name WHERE c.COLUMN_NAME IS NULL;
INSERT INTO _sf_issues SELECT 'Application tables must support rollback',TABLE_NAME FROM information_schema.TABLES
 WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('users','admin_requests','approved_locations','listings','meeting_requests','community_members','community_join_requests') AND ENGINE<>'InnoDB';
