SET @sf_sql=IF(@sf_ready,'INSERT INTO _sf_issues SELECT ''Buyer/outsider must remain Keller nonmembers'',object_name FROM (SELECT u.email AS object_name FROM users u WHERE u.id IN (@sf_buyer,@sf_outsider) AND (EXISTS(SELECT 1 FROM community_members m JOIN admin_requests a ON a.id=m.community_id WHERE m.user_id=u.id AND a.status=''approved'' AND LOWER(TRIM(a.business_name))=''keller properties llc'') OR EXISTS(SELECT 1 FROM admin_requests a WHERE a.user_id=u.id AND a.status=''approved'' AND LOWER(TRIM(a.business_name))=''keller properties llc''))) AS problem','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

