SET @sf_sql=IF(@sf_ready,'INSERT INTO _sf_issues SELECT ''Duplicate candidate listings: choose explicitly, never overwrite'',object_name FROM (SELECT e.title AS object_name FROM _sf_items e JOIN listings l ON CAST(l.name AS BINARY)=CAST(e.title AS BINARY) AND ((e.owner_kind=''seller'' AND l.owner_id=@sf_seller) OR (e.owner_kind=''legacy'' AND l.owner_id IS NULL AND CAST(l.community AS BINARY)=CAST(e.community AS BINARY))) GROUP BY e.variable_name,e.title HAVING COUNT(*)>1) AS problem','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SET @sf_sql=IF(@sf_ready,'INSERT INTO _sf_issues SELECT ''Existing fixture metadata conflict'',object_name FROM (SELECT e.title AS object_name FROM _sf_items e JOIN listings l ON l.listing_id=e.listing_id WHERE (l.price=e.price AND CAST(l.category AS BINARY)=CAST(e.category AS BINARY) AND CAST(l.`condition` AS BINARY)=CAST(''Good'' AS BINARY) AND CAST(l.community AS BINARY)=CAST(e.community AS BINARY) AND (e.owner_kind=''legacy'' OR ((l.meeting_location_id <=> e.location_id) AND (CAST(l.meeting_location AS BINARY) <=> CAST(e.location_label AS BINARY))))) IS NOT TRUE) AS problem','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SET @sf_sql=IF(@sf_ready,'INSERT INTO _sf_issues SELECT ''USED fixture: keep Sold/inactive status and arrivals; use a separately prepared set'',object_name FROM (SELECT e.title AS object_name FROM _sf_items e JOIN listings l ON l.listing_id=e.listing_id LEFT JOIN meeting_requests r ON r.listing_id=l.listing_id WHERE l.status<>''active'' OR r.checked_in_at IS NOT NULL OR r.seller_checked_in_at IS NOT NULL) AS problem','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SET @sf_sql=IF(@sf_ready,'INSERT INTO _sf_issues SELECT ''Unexpected/duplicate meeting: preserve existing records'',object_name FROM (SELECT e.title AS object_name FROM _sf_items e JOIN meeting_requests r ON r.listing_id=e.listing_id GROUP BY e.variable_name,e.title,e.meeting_status HAVING COUNT(*)>1 OR e.meeting_status IS NULL) AS problem','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SET @sf_sql=IF(@sf_ready,'INSERT INTO _sf_issues SELECT ''Existing meeting differs from initial fixture'',object_name FROM (SELECT e.title AS object_name FROM _sf_items e JOIN meeting_requests r ON r.request_id=e.request_id WHERE (r.buyer_id=@sf_buyer AND r.meeting_date=e.meeting_date AND r.meeting_time=e.meeting_time AND r.status=e.meeting_status AND (r.location_id <=> e.location_id) AND (CAST(r.location_label AS BINARY) <=> CAST(e.location_label AS BINARY))) IS NOT TRUE) AS problem','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SET @sf_ready=@sf_ready AND (SELECT COUNT(*)=0 FROM _sf_issues);
SELECT IF(@sf_ready,'READY: insert missing fixtures only','BLOCKED: no application writes') AS fixture_preflight;
