SELECT 'missing_listing_id' AS variable_name,2147483647 AS value;

SET @sf_sql=IF(@sf_ready,'SELECT p.slot,p.location_id,p.label,p.community,p.lat,p.lng FROM _sf_points p ORDER BY p.slot','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SET @sf_sql=IF(@sf_ready,'SELECT e.variable_name,e.listing_id,e.request_id,e.title,l.price,l.status AS listing_status,l.owner_id,r.buyer_id,r.meeting_date,r.meeting_time,r.status AS meeting_status,r.checked_in_at,r.seller_checked_in_at,l.meeting_location,l.meeting_location_id FROM _sf_items e JOIN listings l ON l.listing_id=e.listing_id LEFT JOIN meeting_requests r ON r.request_id=e.request_id ORDER BY e.variable_name','DO 0');
PREPARE sf_stmt FROM @sf_sql; EXECUTE sf_stmt; DEALLOCATE PREPARE sf_stmt;

SELECT RELEASE_LOCK(@sf_lock_name) AS fixture_lock_released;
DROP TEMPORARY TABLE _sf_issues,_sf_columns,_sf_points,_sf_items;
